using System;
using System.Xml;
using System.Runtime.Serialization;
using Microsoft.Xrm.Sdk.Query;
class ColumnSetProbe {
 static void Main(){
  string xml="<v xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:a=\"http://schemas.microsoft.com/xrm/2011/Contracts\" xmlns:f=\"http://schemas.microsoft.com/2003/10/Serialization/Arrays\" i:type=\"a:ColumnSet\"><a:AllColumns>true</a:AllColumns><a:Columns><f:string>name</f:string></a:Columns></v>";
  var doc=new XmlDocument();doc.LoadXml(xml);var serializer=new DataContractSerializer(typeof(object),new Type[]{typeof(ColumnSet)});ColumnSet value;
  using(var reader=new XmlNodeReader(doc.DocumentElement))value=(ColumnSet)serializer.ReadObject(reader,false);
  var nodes=doc.DocumentElement.GetElementsByTagName("Columns","http://schemas.microsoft.com/xrm/2011/Contracts");
  Console.WriteLine(xml);Console.WriteLine("allColumns="+value.AllColumns+";count="+value.Columns.Count+";column="+value.Columns[0]);
  Console.WriteLine("childName="+nodes[0].FirstChild.LocalName+";childNamespace="+nodes[0].FirstChild.NamespaceURI);
 }
}
